<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"><title>Dues receipt</title>
<style>body{font-family:DejaVu Sans,sans-serif;color:#17233b;font-size:12px;padding:30px}h1{font-size:28px;margin:30px 0 8px}h2{font-size:16px}table{width:100%;border-collapse:collapse;margin-top:28px}td{padding:12px 0;border-bottom:1px solid #dde3ec}td:last-child{text-align:right}.muted{color:#596579}.foot{margin-top:40px;font-size:10px}</style></head>
<body><h2>{{ $member->tenant->name }}</h2><h1>Dues receipt</h1><p class="muted">Payment received · {{ $charge->paid_at?->format('j F Y') }}</p>
<table><tr><td>Member</td><td>{{ $member->name }}</td></tr><tr><td>Membership</td><td>{{ $member->membershipType->name }}</td></tr><tr><td>Period</td><td>{{ $charge->period_start->format('j M Y') }} – {{ $charge->period_end->format('j M Y') }}</td></tr><tr><td>Amount paid toward dues</td><td>{{ $charge->currency }} {{ number_format($charge->amount / 100, 2) }}</td></tr><tr><td>Reference</td><td>{{ $charge->payment_reference ?? $charge->id }}</td></tr></table>
<p class="foot muted">Receipt {{ $charge->id }}<br>Generated by MiConvener. This receipt records the dues paid for this period.</p></body></html>
